<script setup>
import {ref,onMounted,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {api,money} from '../services/api'
import {currentUser,identityVersion} from '../services/accounts'
const route=useRoute(),items=ref([]),products=ref([]),error=ref(''),busy=ref(false),filter=ref(''),editing=ref(null),query=ref(''),selectedFigure=ref('')
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`} 
const blank=()=>({variant_id:'',amount:'',currency:'KRW',purchased_on:today(),delivery_status:'pending',shop:'',memo:''})
const form=ref(blank()),status={pending:'배송 대기',shipping:'배송 중',delivered:'배송 완료'}
const visible=computed(()=>items.value.filter(x=>!filter.value||x.delivery_status===filter.value))
const variants=computed(()=>products.value.find(f=>f.id==selectedFigure.value)?.variants||[])
async function load(){const epoch=identityVersion.value;items.value=[];if(!currentUser.value){error.value='로그인 후 구매 기록을 확인할 수 있습니다.';return}const rows=await api('/purchases');if(epoch===identityVersion.value)items.value=rows}
watch(identityVersion,()=>{reset();load().catch(e=>error.value=e.message)})
async function search(){error.value='';try{products.value=(await api('/figures?page_size=100&q='+encodeURIComponent(query.value))).items}catch(e){error.value=e.message}}
function choose(){form.value.variant_id=variants.value[0]?.id||''}
function reset(){editing.value=null;form.value=blank();selectedFigure.value=''}
async function save(){busy.value=true;error.value='';try{await api('/purchases'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:{...form.value,variant_id:Number(form.value.variant_id)}});await load();reset()}catch(e){error.value=e.message}finally{busy.value=false}}
async function edit(row){const epoch=identityVersion.value;error.value='';try{const f=await api('/figures/'+row.figure_id);if(epoch!==identityVersion.value)return;if(!products.value.some(x=>x.id===f.id))products.value.push(f);selectedFigure.value=f.id;editing.value=row.id;form.value={...row};document.getElementById('purchase-form')?.scrollIntoView({behavior:'smooth'})}catch(e){error.value=e.message}}
async function remove(row){if(!confirm('이 구매 기록을 삭제할까요? 상품 자체는 삭제되지 않습니다.'))return;error.value='';try{await api('/purchases/'+row.id,{method:'DELETE'});await load();if(editing.value===row.id)reset()}catch(e){error.value=e.message}}
onMounted(async()=>{try{await Promise.all([load(),search()]);if(route.query.figure){const f=await api('/figures/'+route.query.figure);if(!products.value.some(x=>x.id===f.id))products.value.push(f);selectedFigure.value=f.id;choose();if(f.variants.some(v=>v.id==route.query.variant))form.value.variant_id=Number(route.query.variant)}}catch(e){error.value=e.message}})
</script>
<template><RouterLink v-if="!currentUser" to="/login" class="button">로그인 후 구매 기록 관리</RouterLink><section class="section"><p class="eyebrow">MY COLLECTION</p><h1>구매 완료 목록</h1><p>실제 구매 금액과 배송 상태를 기록하세요. 같은 상품도 구매 건별로 등록할 수 있습니다.</p><p v-if="error" class="error" role="alert">{{error}}</p>
<form v-if="currentUser" id="purchase-form" class="personal-panel" @submit.prevent="save"><h2>{{editing?'구매 기록 수정':'구매 기록 등록'}}</h2><div class="button-row"><input v-model="query" aria-label="상품 검색어" placeholder="상품명 검색"><button type="button" class="button ghost" @click="search">상품 검색</button></div><div class="form-grid"><label>상품<select v-model="selectedFigure" required @change="choose"><option value="" disabled>상품 선택</option><option v-for="f in products" :value="f.id" :key="f.id">{{f.name_ko||f.name_original}}</option></select></label><label>버전<select v-model="form.variant_id" required><option value="" disabled>버전 선택</option><option v-for="v in variants" :value="v.id" :key="v.id">{{v.edition||v.variant_key}} {{v.release_date}}</option></select></label><label>구매 금액<input v-model="form.amount" type="number" min="0" max="999999999999" step="0.01" required></label><label>통화<select v-model="form.currency"><option>KRW</option><option>JPY</option><option>USD</option></select></label><label>구매일<input v-model="form.purchased_on" type="date" :max="today()" required></label><label>배송 상태<select v-model="form.delivery_status"><option v-for="(label,key) in status" :value="key" :key="key">{{label}}</option></select></label><label>구매처<input v-model="form.shop" maxlength="200"></label><label>메모<textarea v-model="form.memo" maxlength="2000"></textarea></label></div><div class="button-row"><button class="button" :disabled="busy">{{busy?'저장 중…':editing?'수정 저장':'구매 완료 등록'}}</button><button type="button" class="button ghost" @click="reset">초기화</button></div></form>
<label>배송 상태 필터<select v-model="filter"><option value="">전체</option><option v-for="(label,key) in status" :key="key" :value="key">{{label}}</option></select></label><p v-if="!visible.length" class="empty">등록된 구매 기록이 없습니다.</p><article class="personal-panel" v-for="row in visible" :key="row.id"><h3><RouterLink :to="'/figures/'+row.figure_id">{{row.name}}</RouterLink></h3><p>{{row.edition}} · {{row.purchased_on}} · {{row.shop||'구매처 미입력'}}</p><p><strong>{{money(row.amount,row.currency)}}</strong> · {{status[row.delivery_status]}}</p><p class="preserve-lines">{{row.memo}}</p><div class="button-row"><button class="button ghost" @click="edit(row)">수정 / 배송 상태 변경</button><button class="button ghost" @click="remove(row)">삭제</button></div></article></section></template>
